import{_ as o,o as r,c as t,a2 as a}from"./chunks/framework.lxr64Vqo.js";const p=JSON.parse('{"title":"Frequently Asked Questions (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1795176281000}'),i={name:"faq.md"};function s(n,e,d,l,h,c){return r(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="frequently-asked-questions-faq" tabindex="-1">Frequently Asked Questions (FAQ) <a class="header-anchor" href="#frequently-asked-questions-faq" aria-label="Permalink to &quot;Frequently Asked Questions (FAQ)&quot;">​</a></h1><p>Find answers to common questions regarding NoxMedia setup, streaming protocols, and client compatibility.</p><hr><h3 id="does-noxmedia-download-whole-files-to-host-device-storage" tabindex="-1">Does NoxMedia download whole files to host device storage? <a class="header-anchor" href="#does-noxmedia-download-whole-files-to-host-device-storage" aria-label="Permalink to &quot;Does NoxMedia download whole files to host device storage?&quot;">​</a></h3><p><strong>No.</strong> NoxMedia functions as a real-time streaming bridge. When you initiate playback on Infuse, Vesper, or Nuvio, NoxMedia requests stream byte chunks directly from Telegram&#39;s servers and pipes them over HTTP directly to your player. Host device storage is not consumed by media files.</p><hr><h3 id="is-noxmedia-completely-free" tabindex="-1">Is NoxMedia completely free? <a class="header-anchor" href="#is-noxmedia-completely-free" aria-label="Permalink to &quot;Is NoxMedia completely free?&quot;">​</a></h3><p><strong>Yes.</strong> NoxMedia is free and open-source under the AGPLv3 / MIT licenses. There are no subscriptions, paywalls, or feature tiers.</p><hr><h3 id="can-i-stream-outside-my-home-wi-fi-network" tabindex="-1">Can I stream outside my home Wi-Fi network? <a class="header-anchor" href="#can-i-stream-outside-my-home-wi-fi-network" aria-label="Permalink to &quot;Can I stream outside my home Wi-Fi network?&quot;">​</a></h3><p><strong>Yes.</strong> There are multiple supported methods to access your server remotely:</p><ol><li><strong>Tailscale / WireGuard (Recommended)</strong>: Install Tailscale on your host device and your remote device (iPhone, laptop). You obtain a secure private mesh IP (e.g., <code>http://100.x.y.z:7788</code>).</li><li><strong>Cloudflare Tunnels</strong>: Route port 7788 through a Cloudflare tunnel to your personal domain.</li><li><strong>Router Port Forwarding</strong>: Forward external port <code>7788</code> to your host device&#39;s local IP address in router administration.</li></ol><hr><h3 id="why-does-infuse-show-an-indexing-error-in-library-mode" tabindex="-1">Why does Infuse show an indexing error in Library Mode? <a class="header-anchor" href="#why-does-infuse-show-an-indexing-error-in-library-mode" aria-label="Permalink to &quot;Why does Infuse show an indexing error in Library Mode?&quot;">​</a></h3><p>In Infuse Settings -&gt; <strong>Library</strong>, do not enable full background library indexing on the NoxMedia share. Because Telegram channels often contain thousands of files, Infuse&#39;s recursive library crawler can exceed local network timeouts. Instead, browse through <strong>Files -&gt; NoxMedia</strong> (<strong>Direct Mode</strong>), which streams folder structures on-demand with zero-latency caching.</p><hr><h3 id="does-noxmedia-work-with-vesper" tabindex="-1">Does NoxMedia work with Vesper? <a class="header-anchor" href="#does-noxmedia-work-with-vesper" aria-label="Permalink to &quot;Does NoxMedia work with Vesper?&quot;">​</a></h3><p><strong>Yes.</strong> Vesper connects seamlessly using the Jellyfin server protocol (<code>http://&lt;HOST_IP&gt;:7788</code>), offering high-speed playback across macOS, iOS, iPadOS, and tvOS.</p><hr><h3 id="what-is-the-current-status-of-stremio-support" tabindex="-1">What is the current status of Stremio support? <a class="header-anchor" href="#what-is-the-current-status-of-stremio-support" aria-label="Permalink to &quot;What is the current status of Stremio support?&quot;">​</a></h3><p>Direct playback in Stremio is temporarily on hold while we resolve an issue related to Stremio&#39;s handling of localhost HTTP streaming endpoints on Android. In the interim, <strong>Nuvio</strong> is the officially recommended client for addon-based playback on Android, Windows, Mac, and Web.</p><hr><h3 id="what-video-and-audio-codecs-are-supported" tabindex="-1">What video and audio codecs are supported? <a class="header-anchor" href="#what-video-and-audio-codecs-are-supported" aria-label="Permalink to &quot;What video and audio codecs are supported?&quot;">​</a></h3><p>Because NoxMedia serves direct media streams, codec support is determined by your client player:</p><ul><li><strong>Infuse &amp; Vesper</strong>: Plays virtually all formats natively (4K HDR10, Dolby Vision, HEVC/H.265, AV1, DTS-HD MA, Dolby TrueHD Atmos, FLAC).</li><li><strong>Nuvio</strong>: Supports modern video formats via hardware decoders.</li><li><strong>Kodi</strong>: Plays all raw remuxes and multi-channel audio tracks.</li></ul><hr><h3 id="can-noxmedia-stream-files-packed-inside-zip-archives" tabindex="-1">Can NoxMedia stream files packed inside <code>.zip</code> archives? <a class="header-anchor" href="#can-noxmedia-stream-files-packed-inside-zip-archives" aria-label="Permalink to &quot;Can NoxMedia stream files packed inside `.zip` archives?&quot;">​</a></h3><p><strong>Yes, for uncompressed archives.</strong></p><ul><li><strong>Store Mode (0% Compression)</strong>: Works seamlessly. Because media files (like <code>.mkv</code> or <code>.mp4</code>) are already compressed, packing them with <code>Store</code> mode allows NoxMedia to perform random byte seeks on-demand directly from Telegram&#39;s cloud.</li><li><strong>Compressed Archives (Deflate)</strong>: Detected and cataloged in your library with full artwork and metadata, but real-time random seeking is not supported as decompression must begin from byte 0.</li></ul><hr><h3 id="why-can-t-i-host-the-noxmedia-server-on-iphone-or-ipad" tabindex="-1">Why can&#39;t I host the NoxMedia server on iPhone or iPad? <a class="header-anchor" href="#why-can-t-i-host-the-noxmedia-server-on-iphone-or-ipad" aria-label="Permalink to &quot;Why can&#39;t I host the NoxMedia server on iPhone or iPad?&quot;">​</a></h3><p>Apple&#39;s iOS security architecture strictly prohibits long-running background network socket listeners. iOS suspends or terminates background processes within 30 seconds of the device being locked or minimized. However, <strong>you can seamlessly watch NoxMedia streams on iOS</strong> by connecting your Apple device (iPhone, iPad, Mac, Apple TV, Vision Pro) to your Android host server using <strong>Infuse</strong>, <strong>Vesper</strong>, or <strong>Nuvio</strong>!</p><hr><h3 id="how-do-i-find-private-telegram-channel-ids" tabindex="-1">How do I find private Telegram channel IDs? <a class="header-anchor" href="#how-do-i-find-private-telegram-channel-ids" aria-label="Permalink to &quot;How do I find private Telegram channel IDs?&quot;">​</a></h3><ol><li>Open <a href="https://t.me/idbot" target="_blank" rel="noreferrer">@idbot</a> or <a href="https://t.me/userinfobot" target="_blank" rel="noreferrer">@userinfobot</a> in Telegram.</li><li>Forward any video or message from your private channel into the bot.</li><li>The bot will reply with the channel&#39;s unique ID (e.g., <code>-1001234567890</code>).</li><li>Copy the entire ID including the <code>-100</code> prefix and paste it into NoxMedia&#39;s <strong>Channels</strong> tab.</li></ol><hr><h3 id="how-do-i-keep-the-server-running-24-7-without-android-killing-it" tabindex="-1">How do I keep the server running 24/7 without Android killing it? <a class="header-anchor" href="#how-do-i-keep-the-server-running-24-7-without-android-killing-it" aria-label="Permalink to &quot;How do I keep the server running 24/7 without Android killing it?&quot;">​</a></h3><ol><li><strong>Set Battery to Unrestricted</strong>: Go to Android <strong>Settings</strong> -&gt; <strong>Apps</strong> -&gt; <strong>NoxMedia</strong> -&gt; <strong>Battery</strong> -&gt; Select <strong>Unrestricted</strong>.</li><li><strong>Lock in Recent Apps</strong>: Open the Android task switcher, long-press NoxMedia, and tap the <strong>Lock</strong> icon (on MIUI/HyperOS, OxygenOS, or OneUI).</li><li><strong>Exclude from App Killers</strong>: Add NoxMedia to your OEM&#39;s background whitelist so battery optimizers do not terminate the background service.</li></ol>',38)])])}const m=o(i,[["render",s]]);export{p as __pageData,m as default};
